          <h2 className="font-serif text-4xl md:text-5xl font-bold mb-6" data-testid="media-kit-title">
            Media Kit
          </h2>
          <p className="text-lg text-muted-foreground max-w-2xl mx-auto" data-testid="media-kit-subtitle">
            Professional assets for media, press, and collaboration opportunities
          </p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 mb-16">
          {mediaAssets.map((asset, index) => (
            <div 
              key={asset.name}
              className="luxury-card group relative bg-card border border-border rounded-lg p-6 hover:shadow-2xl transition-all duration-500"
              data-testid={`media-asset-${index}`}
            >
              {/* Type Badge */}
              <div className="flex items-center justify-between mb-4">
                <div className={`inline-flex items-center gap-2 px-3 py-1 rounded-full text-sm font-medium border ${getTypeColor(asset.type)}`}>
                  {asset.icon}
                  {getTypeLabel(asset.type)}
                </div>
                {asset.fileSize && (
                  <span className="text-xs text-muted-foreground">
                    {asset.fileSize}
                  </span>
                )}
              </div>

              {/* Asset Info */}
              <div className="mb-6">
                <h3 className="text-lg font-bold mb-2 group-hover:text-primary transition-colors">
                  {asset.name}
                </h3>
                <p className="text-sm text-muted-foreground leading-relaxed">
                  {asset.description}
                </p>
              </div>

              {/* Download Button */}
              <button className="luxury-button w-full inline-flex items-center justify-center gap-2 px-4 py-3 bg-primary text-primary-foreground font-medium rounded-lg hover:bg-primary/90 transition-all duration-300 hover:scale-105">
                <Download className="w-4 h-4" />
                Download
              </button>

              {/* Hover Line */}
              <div className="absolute bottom-0 left-0 w-full h-px bg-gradient-to-r from-transparent via-primary to-transparent transform scale-x-0 group-hover:scale-x-100 transition-transform duration-500"></div>
            </div>
          ))}
        </div>

        {/* Contact Information */}
        <div className="text-center" data-testid="media-kit-contact">
          <div className="luxury-card inline-block bg-card border border-border rounded-xl p-8">
            <div className="flex items-center justify-center w-16 h-16 bg-primary/10 text-primary rounded-full mx-auto mb-6">
              <Mail className="w-8 h-8" />
            </div>

            <h3 className="text-xl font-bold mb-2">Media Inquiries</h3>
            <p className="text-muted-foreground mb-6 max-w-sm">
              For interviews, speaking engagements, or collaboration opportunities
            </p>

            <div className="flex flex-col sm:flex-row gap-4 justify-center">
              <a 
                href="mailto:media@kiminouknox.com"
                className="luxury-button inline-flex items-center gap-2 px-6 py-3 bg-primary text-primary-foreground font-medium rounded-lg hover:bg-primary/90 transition-all duration-300 hover:scale-105"
              >
                <Mail className="w-4 h-4" />
                Contact Media Team
              </a>
              <a 
                href="#contact"
                className="inline-flex items-center gap-2 px-6 py-3 border border-border font-medium rounded-lg hover:bg-accent hover:text-accent-foreground transition-colors"
              >
                <ExternalLink className="w-4 h-4" />
                View Full Contact
              </a>
            </div>
          </div>
        </div>

        {/* Usage Guidelines */}
        <div className="mt-16 text-center text-sm text-muted-foreground">
          <p>
            All media assets are provided for editorial use. 
            Commercial use requires written permission. 
            Please credit "Kiminou Knox" in all publications.
          </p>
        </div>
      </div>
    </section>
  );
}

client/src/pages/Works.tsx.content:
import { Helmet } from "react-helmet";
import { useState, useEffect } from "react";
import Header from "@/components/Header";
import Footer from "@/components/Footer";
import { Button } from "@/components/ui/button";
import { ExternalLink } from "lucide-react";

interface Book {
  id: string;
  title: string;
  subtitle: string;
  year: number;
  datePublished: string;
  isbn: string;
  cover: string;
  description: string;
  buyLinks: Record<string, string>;
}

export default function Works() {
  const [books, setBooks] = useState<Book[]>([]);

  useEffect(() => {
    fetch('/books-full.json')
      .then(res => res.json())
      .then(data => setBooks(data))
      .catch(err => console.error('Failed to load books:', err));
  }, []);

  const bookSchemas = books.map(book => ({
    "@context": "https://schema.org",
    "@type": "Book",
    "@id": `https://kiminouknox.com/works#${book.id}`,
    "name": book.title,
    "author": { "@id": "https://kiminouknox.com/#person" },
    "workExample": [
      { "@type": "Book", "bookFormat": "https://schema.org/EBook", "url": book.buyLinks.amazon || book.buyLinks.googleBooks || "" },
      { "@type": "Book", "bookFormat": "https://schema.org/Paperback", "url": book.buyLinks.amazon || "" }
    ],
    "offers": {
      "@type": "Offer",
      "url": book.buyLinks.amazon || "",
      "availability": "https://schema.org/InStock"
    }
  }));

  return (
    <>
      <Helmet>
        <title>Works - Kiminou Knox</title>
        <meta name="description" content="Books by Kiminou Knox: Black Boy Poems, Our Father, Boys Raised in Silence, The Spirit of Solomon, Hopeless Romantic, and The Adventures of Kiminou the Great and Chua the Wise." />
        <link rel="canonical" href="https://kiminouknox.com/works" />

        <meta property="og:type" content="website" />
        <meta property="og:title" content="Works - Kiminou Knox" />
        <meta property="og:description" content="Published works and books by writer Kiminou Knox" />
        <meta property="og:url" content="https://kiminouknox.com/works" />
        <meta property="og:image" content="https://kiminouknox.com/og/works.jpg" />

        <meta name="twitter:card" content="summary_large_image" />
        <meta name="twitter:title" content="Works - Kiminou Knox" />
        <meta name="twitter:description" content="Published books and poetry collections" />
        <meta name="twitter:image" content="https://kiminouknox.com/og/works.jpg" />

        {bookSchemas.map((schema, index) => (
          <script key={index} type="application/ld+json">
            {JSON.stringify(schema)}
          </script>
        ))}
      </Helmet>

      <Header />

      <main className="min-h-screen bg-background pt-32 pb-20">
        <div className="max-w-7xl mx-auto px-6 lg:px-8">
          <div className="mb-16 text-center">
            <h1 className="text-5xl lg:text-6xl font-serif font-bold mb-6 text-foreground" data-testid="works-heading">
              Works
            </h1>
            <p className="text-lg text-muted-foreground max-w-2xl mx-auto">
              Poetry collections and stories exploring faith identity love and the Black experience
            </p>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
