client/src/components/ContactForm.tsx.content:
import { useState } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { contactFormSchema, type ContactForm as ContactFormType } from "@shared/schema";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { useToast } from "@/hooks/use-toast";

interface ContactFormProps {
  defaultInquiryType?: "speaking" | "press" | "book" | "basketball" | "other";
  title?: string;
  description?: string;
  showOrganization?: boolean;
  showSpeakingFields?: boolean;
  successMessage?: string;
  className?: string;
}

export default function ContactForm({
  defaultInquiryType = "other",
  title = "Get in Touch",
  description = "Fill out the form below and we'll get back to you as soon as possible.",
  showOrganization = false,
  showSpeakingFields = false,
  successMessage = "Thank you for your message. We will be in touch soon.",
  className = "",
}: ContactFormProps) {
  const { toast } = useToast();
  const [isSubmitting, setIsSubmitting] = useState(false);

  const form = useForm<ContactFormType>({
    resolver: zodResolver(contactFormSchema),
    defaultValues: {
      name: "",
      email: "",
      inquiryType: defaultInquiryType,
      organization: "",
      subject: "",
      message: "",
      dateWindow: "",
      talkTheme: "",
    },
  });

  const inquiryType = form.watch("inquiryType");
  const shouldShowOrganization = showOrganization || inquiryType === "press" || inquiryType === "speaking";
  const shouldShowSpeakingFields = showSpeakingFields || inquiryType === "speaking";

  const onSubmit = async (data: ContactFormType) => {
    setIsSubmitting(true);

    try {
      const response = await fetch("/api/contact", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(data),
      });

      if (response.ok) {
        toast({
          title: "Message sent successfully",
          description: successMessage,
        });
        form.reset({
          name: "",
          email: "",
          inquiryType: defaultInquiryType,
          organization: "",
          subject: "",
          message: "",
          dateWindow: "",
          talkTheme: "",
        });
      } else {
        throw new Error("Submission failed");
      }
    } catch (error) {
      toast({
        title: "Submission failed",
        description: "Please try again or contact us directly at knoxkiminou1@gmail.com",
        variant: "destructive",
      });
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className={className}>
      {(title || description) && (
        <div className="mb-8">
          {title && (
            <h2 className="font-serif text-3xl font-bold mb-4" data-testid="contact-form-title">
              {title}
            </h2>
          )}
          {description && (
            <p className="text-muted-foreground" data-testid="contact-form-description">
              {description}
            </p>
          )}
        </div>
      )}

      <Form {...form}>
        <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6">
          {/* Name */}
          <FormField
            control={form.control}
            name="name"
            render={({ field }) => (
              <FormItem>
                <FormLabel>Name</FormLabel>
                <FormControl>
                  <Input placeholder="Your full name" {...field} data-testid="input-name" />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />

          {/* Email */}
          <FormField
            control={form.control}
            name="email"
            render={({ field }) => (
              <FormItem>
                <FormLabel>Email</FormLabel>
                <FormControl>
                  <Input type="email" placeholder="your.email@example.com" {...field} data-testid="input-email" />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />

          {/* Inquiry Type */}
          <FormField
            control={form.control}
            name="inquiryType"
            render={({ field }) => (
              <FormItem>
                <FormLabel>Inquiry Type</FormLabel>
                <Select onValueChange={field.onChange} defaultValue={field.value}>
                  <FormControl>
                    <SelectTrigger data-testid="select-inquiry-type">
                      <SelectValue placeholder="Select inquiry type" />
                    </SelectTrigger>
                  </FormControl>
                  <SelectContent>
                    <SelectItem value="speaking">Speaking / Appearance</SelectItem>
                    <SelectItem value="press">Press / Media</SelectItem>
                    <SelectItem value="book">Book / Author</SelectItem>
                    <SelectItem value="basketball">Basketball / Athlete</SelectItem>
                    <SelectItem value="other">Other</SelectItem>
                  </SelectContent>
                </Select>
                <FormMessage />
              </FormItem>
            )}
          />

          {/* Organization (conditional) */}
          {shouldShowOrganization && (
            <FormField
              control={form.control}
              name="organization"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Organization (optional)</FormLabel>
                  <FormControl>
                    <Input placeholder="Your organization or affiliation" {...field} data-testid="input-organization" />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />
          )}

          {/* Speaking-specific fields */}
          {shouldShowSpeakingFields && (
            <>
              <FormField
                control={form.control}
                name="dateWindow"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Preferred Date Window (optional)</FormLabel>
                    <FormControl>
                      <Input placeholder="e.g., March 2025" {...field} data-testid="input-date-window" />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name="talkTheme"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Talk Theme (optional)</FormLabel>
                    <FormControl>
                      <Input placeholder="e.g., Youth Leadership, Creative Writing" {...field} data-testid="input-talk-theme" />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
            </>
          )}

          {/* Subject */}
          <FormField
            control={form.control}
            name="subject"
            render={({ field }) => (
              <FormItem>
                <FormLabel>Subject</FormLabel>
                <FormControl>
                  <Input placeholder="Brief subject line" {...field} data-testid="input-subject" />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />

          {/* Message */}
          <FormField
            control={form.control}
            name="message"
            render={({ field }) => (
              <FormItem>
                <FormLabel>Message</FormLabel>
                <FormControl>
                  <Textarea
                    placeholder="Tell us more about your inquiry..."
                    className="min-h-[150px]"
                    {...field}
                    data-testid="textarea-message"
                  />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />

          <Button
            type="submit"
            disabled={isSubmitting}
            className="w-full"
            data-testid="button-submit-contact"
          >
            {isSubmitting ? "Sending..." : "Send Message"}
          </Button>
        </form>
      </Form>
    </div>
  );
}
